import React, { useState, useEffect } from 'react';
import './Orders.css'; // Add this line for external CSS
import axios from 'axios';

const Orders = () => {
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    const fetchOrders = async () => {
      try {
        const response = await axios.get('http://localhost:5000/api/orders');
        setOrders(response.data);
      } catch (error) {
        console.error('Error fetching orders:', error);
      }
    };

    fetchOrders();
  }, []);

  return (
    <div className="orders-container">
      <h2 className="orders-title">Available Orders</h2>
      {orders.length > 0 ? (
        <div className="orders-list">
          {orders.map((order) => (
            <div key={order._id} className="order-card">
              <h3>Order ID: {order.orderId}</h3>
              <img src={order.productImage} alt={order.productName} className="product-image" />
              <p><strong>Product Name:</strong> {order.productName}</p>
              <p><strong>Product Type:</strong> {order.productType}</p>
              <p><strong>Price:</strong> {order.productPrice}</p>
              <p><strong>Description:</strong> {order.productDescription}</p>
              <h4>Order Stages:</h4>
              <ul>
                {order.status.map((stage, index) => (
                  <li key={index}>
                    <strong>{stage.stage}:</strong> {stage.completed ? 'Completed' : 'Not Completed'} - {stage.description}
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      ) : (
        <p>No orders available</p>
      )}
    </div>
  );
};

export default Orders;
